<!DOCTYPE html> 
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Subsidized Rail Tie ROI Dashboard</title>
    <!-- 1. External Libraries -->
    <link href="https://fonts.googleapis.com/css2?family=Material+Icons" rel="stylesheet">
    <link href="https://fonts.googleapis.com/css2?family=Google+Sans:wght@300;350;400;500;700&family=Google+Sans+Flex:wght@300;350;400;500;700&family=Google+Sans+Code:wght@300;400;500;700&family=Google+Code:wght@400;500;700&family=Roboto:wght@400;500;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/mathjs/12.4.0/math.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/d3@7.9.0"></script>
    <script src="https://cdn.jsdelivr.net/npm/@observablehq/plot@0.6.16"></script>
    <script src="https://cdn.tailwindcss.com"></script>

    <!-- 2. CSS Design System -->
    <style>
        :root {
            --primary: #0b57d0;
            --on-primary: #fff;
            --primary-container: #d3e3fd;
            --on-primary-container: #041e49;
            --surface: #ffffff;
            --surface-container: #f0f4f9;
            --on-surface-default: #1b1c1d;
            --on-surface-de-emphasis: #444746;
            --stroke-default: #dcdfe5;
            --success: #146c2e;
            --error: #b3261e;
            --ff-sans: "Google Sans","Roboto",sans-serif;
        }
        body {
            font-family: var(--ff-sans);
            color: var(--on-surface-default);
            background-color: var(--surface-container);
        }
        .custom-slider-track {
            height: 6px;
            border-radius: 3px;
        }
    </style>
</head>
<body class="spark-widget-shell p-4">

    <!-- STREAMING_CHUNK:Initializing widget container layout... -->
    <div class="widget-container max-w-6xl mx-auto bg-white rounded-xl shadow-md overflow-hidden p-6 gap-6 flex flex-col">
        <div class="widget-header flex flex-col gap-2 pb-4 border-b border-gray-100">
            <h3 class="widget-title text-2xl font-semibold text-gray-800">Subsidized Rail Tie ROI Dashboard</h3>
            <p class="text-sm text-gray-500">Evaluate the interactive impact of Section 45X production credits and Federal Infrastructure Grants on payback timelines.</p>
        </div>

        <!-- Dashboard HUD Area -->
        <div id="widget-dashboard" class="widget-dashboard flex flex-wrap gap-4 justify-between bg-slate-50 p-4 rounded-xl border border-gray-100">
            <!-- Dynamic HUD pills will be rendered here -->
        </div>

        <!-- Viz Container -->
        <div class="viz-container relative bg-slate-50 rounded-xl p-4 border border-gray-100" style="min-height: 380px;">
            <div id="viz" class="w-full h-full"></div>
            <div id="viz-legend" class="absolute bottom-4 left-4 bg-white/95 backdrop-blur px-3 py-2 rounded-lg border border-gray-200 text-xs flex gap-4 pointer-events-none shadow-sm">
                <div class="flex items-center gap-1.5"><span class="w-3 h-3 rounded-full bg-blue-600 block"></span><span class="font-medium">Subsidized Cash Flow</span></div>
                <div class="flex items-center gap-1.5"><span class="w-3 h-3 border-t-2 border-dashed border-gray-400 block"></span><span class="font-medium">Unsubsidized Cash Flow</span></div>
            </div>
        </div>

        <!-- Controls Grid -->
        <div id="controls-root" class="controls-root grid grid-cols-1 md:grid-cols-2 gap-6 pt-4 border-t border-gray-100">
            <!-- Controls injected here via JS -->
        </div>
    </div>

    <!-- 3. Core App Script -->
    <script>
        /* STREAMING_CHUNK:Configuring state and formatting modules... */
        const { state } = WH.createApp({
            title: "Subsidized Smart Tie ROI",
            params: {
                unsubcapex: { value: 2744073, min: 1000000, max: 5000000, step: 10000, label: "Unsubsidized CapEx Premium ($)" },
                annualInflux: { value: 705418, min: 200000, max: 1500000, step: 5000, label: "Net Annual Influx ($/yr)" },
                has45X: { value: true, label: "Include Section 45X Tax Credits ($202.50/tie)" },
                grantShare: { value: 50, min: 0, max: 80, step: 10, label: "Federal Grant Share (%)" }
            },
            internal_state: {
                unsubPoints: [],
                subPoints: [],
                subsidizedPremium: 0,
                breakEvenYear: 0,
                unsubBreakEvenYear: 0
            }
        });

        const fmt = new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            maximumFractionDigits: 0
        });

        /* STREAMING_CHUNK:Implementing mathematical ROI algorithms... */
        const updateCalculations = () => {
            const woodBaseline = 243750; // Cost of 3,250 wooden ties @ $75 each
            const totalProjectCost = Number(state.unsubcapex) + woodBaseline;

            // S.45X offers $225/tie (stacked cell + module). Monetized via transferability at $0.90 on the dollar
            const credit45X = state.has45X ? (3250 * 202.50) : 0;
            const grantAmount = totalProjectCost * (Number(state.grantShare) / 100);

            const subsidizedTieCost = totalProjectCost - grantAmount - credit45X;
            let subsidizedPremium = subsidizedTieCost - woodBaseline;
            if (subsidizedPremium < 0) subsidizedPremium = 0; // Cap at zero premium (fully funded)

            const unsubPoints = [];
            const subPoints = [];
            const horizon = 20;

            for (let yr = 0; yr <= horizon; yr++) {
                unsubPoints.push({
                    year: yr,
                    cf: -state.unsubcapex + (state.annualInflux * yr)
                });
                subPoints.push({
                    year: yr,
                    cf: -subsidizedPremium + (state.annualInflux * yr)
                });
            }

            state.unsubPoints = unsubPoints;
            state.subPoints = subPoints;
            state.subsidizedPremium = subsidizedPremium;
            state.breakEvenYear = state.annualInflux > 0 ? (subsidizedPremium / state.annualInflux) : 0;
            state.unsubBreakEvenYear = state.annualInflux > 0 ? (state.unsubcapex / state.annualInflux) : 0;

            const y10 = -subsidizedPremium + (state.annualInflux * 10);
            const y20 = -subsidizedPremium + (state.annualInflux * 20);

            // Dynamically update the HUD
            const hudContainer = document.getElementById('widget-dashboard');
            hudContainer.innerHTML = '';

            const metrics = [
                { label: "Subsidized Break-Even", value: state.breakEvenYear === 0 ? "Instant (Fully Funded)" : `${state.breakEvenYear.toFixed(1)} yrs`, color: "text-blue-600" },
                { label: "Subsidized CapEx Premium", value: fmt.format(subsidizedPremium), color: "text-amber-600" },
                { label: "Year 10 Cumulative Flow", value: fmt.format(y10), color: "text-emerald-600" }
            ];

            metrics.forEach(m => {
                const pill = document.createElement('div');
                pill.className = "flex flex-col flex-1 min-w-[200px] border-r border-gray-200 last:border-0 pr-4 last:pr-0";
                pill.innerHTML = `
                    <span class="text-xs font-semibold text-gray-500 uppercase tracking-wider">${m.label}</span>
                    <span class="text-xl font-bold ${m.color} mt-1">${m.value}</span>
                `;
                hudContainer.appendChild(pill);
            });

            // Update WH Editorial panel just in case
            ui.setEditorial({
                hud: [
                    { label: "Subsidized Break-Even", value: state.breakEvenYear === 0 ? "Instant" : `${state.breakEvenYear.toFixed(1)} yrs` },
                    { label: "Subsidized CapEx Premium", value: fmt.format(subsidizedPremium) },
                    { label: "Year 10 Flow", value: fmt.format(y10) }
                ]
            });
        };

        /* STREAMING_CHUNK:Subscribing to system variables... */
        state._subscribe('unsubcapex', updateCalculations);
        state._subscribe('annualInflux', updateCalculations);
        state._subscribe('has45X', updateCalculations);
        state._subscribe('grantShare', updateCalculations);

        // Bootstrap calculations
        updateCalculations();

        /* STREAMING_CHUNK:Configuring interactive layout controls... */
        const controlsRoot = document.getElementById('controls-root');

        // Control: Unsubsidized CapEx Slider
        const capexRow = document.createElement('div');
        capexRow.className = "flex flex-col gap-2";
        capexRow.innerHTML = `
            <label class="text-sm font-semibold text-gray-700">Unsubsidized CapEx Premium ($)</label>
            <div class="flex items-center gap-4">
                <input type="range" min="1000000" max="5000000" step="10000" value="${state.unsubcapex}" class="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600" id="capex-slider">
                <span class="text-sm font-mono font-bold text-gray-700 min-w-[90px] text-right" id="capex-readout">${fmt.format(state.unsubcapex)}</span>
            </div>
        `;
        controlsRoot.appendChild(capexRow);

        // Control: Net Annual Influx Slider
        const influxRow = document.createElement('div');
        influxRow.className = "flex flex-col gap-2";
        influxRow.innerHTML = `
            <label class="text-sm font-semibold text-gray-700">Net Annual Influx ($/yr)</label>
            <div class="flex items-center gap-4">
                <input type="range" min="200000" max="1500000" step="5000" value="${state.annualInflux}" class="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600" id="influx-slider">
                <span class="text-sm font-mono font-bold text-gray-700 min-w-[90px] text-right" id="influx-readout">${fmt.format(state.annualInflux)}</span>
            </div>
        `;
        controlsRoot.appendChild(influxRow);

        // Control: Section 45X Toggle
        const toggleRow = document.createElement('div');
        toggleRow.className = "flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-200";
        toggleRow.innerHTML = `
            <div class="flex flex-col">
                <span class="text-sm font-semibold text-gray-700">Section 45X Production Credits</span>
                <span class="text-xs text-gray-500">Applies $225/tie module credit monetized at 90%</span>
            </div>
            <label class="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" id="toggle-45x" class="sr-only peer" ${state.has45X ? 'checked' : ''}>
                <div class="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
            </label>
        `;
        controlsRoot.appendChild(toggleRow);

        // Control: Federal Grant Slider
        const grantRow = document.createElement('div');
        grantRow.className = "flex flex-col gap-2";
        grantRow.innerHTML = `
            <label class="text-sm font-semibold text-gray-700">Federal Cost-Share Grant (%)</label>
            <div class="flex items-center gap-4">
                <input type="range" min="0" max="80" step="10" value="${state.grantShare}" class="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600" id="grant-slider">
                <span class="text-sm font-mono font-bold text-gray-700 min-w-[40px] text-right" id="grant-readout">${state.grantShare}%</span>
            </div>
        `;
        controlsRoot.appendChild(grantRow);

        // Event listeners
        document.getElementById('capex-slider').oninput = (e) => {
            const val = Number(e.target.value);
            state.unsubcapex = val;
            document.getElementById('capex-readout').textContent = fmt.format(val);
        };
        document.getElementById('influx-slider').oninput = (e) => {
            const val = Number(e.target.value);
            state.annualInflux = val;
            document.getElementById('influx-readout').textContent = fmt.format(val);
        };
        document.getElementById('toggle-45x').onchange = (e) => {
            state.has45X = e.target.checked;
        };
        document.getElementById('grant-slider').oninput = (e) => {
            const val = Number(e.target.value);
            state.grantShare = val;
            document.getElementById('grant-readout').textContent = `${val}%`;
        };

        /* STREAMING_CHUNK:Generating rendering engine for ROI plot... */
        WH.initPlot('viz', ({ width, height, state }) => {
            const subData = [...state.subPoints];
            const unsubData = [...state.unsubPoints];
            const beY = state.breakEvenYear;
            const unsubBeY = state.unsubBreakEvenYear;

            const bePoint = beY > 0 && beY <= 20 ? [{ year: beY, cf: 0 }] : [];
            const unsubBePoint = unsubBeY > 0 && unsubBeY <= 20 ? [{ year: unsubBeY, cf: 0 }] : [];

            return {
                width,
                height,
                marginLeft: 75,
                marginBottom: 45,
                x: { 
                    label: "Operation Year", 
                    domain: [0, 20], 
                    grid: true 
                },
                y: { 
                    label: "Cumulative Cash Flow ($)", 
                    tickFormat: d => d === 0 ? "0" : fmt.format(d),
                    grid: true
                },
                marks: [
                    // Baseline zero marker
                    Plot.ruleY([0], { stroke: "var(--stroke-default)", strokeWidth: 1.5 }),

                    // Shaded Profit Zone for Subsidized Curve
                    Plot.areaY(subData, { 
                        x: "year", 
                        y1: 0, 
                        y2: d => Math.max(0, d.cf), 
                        fill: "var(--success)", 
                        fillOpacity: 0.12 
                    }),

                    // Shaded Loss Zone for Subsidized Curve
                    Plot.areaY(subData, { 
                        x: "year", 
                        y1: 0, 
                        y2: d => Math.min(0, d.cf), 
                        fill: "var(--error)", 
                        fillOpacity: 0.12 
                    }),

                    // Unsubsidized Reference Path
                    Plot.lineY(unsubData, { 
                        x: "year", 
                        y: "cf", 
                        stroke: "#94a3b8", 
                        strokeWidth: 2,
                        strokeDasharray: "5,5"
                    }),

                    // Subsidized Active Path
                    Plot.lineY(subData, { 
                        x: "year", 
                        y: "cf", 
                        stroke: "#2563eb", 
                        strokeWidth: 3.5 
                    }),

                    // Subsidized Break-Even Node
                    Plot.dot(bePoint, { 
                        x: "year", 
                        y: "cf", 
                        fill: "#1e3a8a", 
                        stroke: "#ffffff",
                        strokeWidth: 2.5,
                        r: 6 
                    }),

                    // Subsidized Break-Even Label
                    Plot.text(bePoint, { 
                        x: "year", 
                        y: "cf", 
                        text: d => `Subsidized Break-Even: ${d.year.toFixed(1)} yrs`, 
                        dy: -18,
                        fontWeight: "bold",
                        fill: "#1e3a8a",
                        stroke: "#ffffff",
                        strokeWidth: 4,
                        paintOrder: "stroke"
                    }),

                    // Unsubsidized Break-Even Node
                    Plot.dot(unsubBePoint, { 
                        x: "year", 
                        y: "cf", 
                        fill: "#64748b", 
                        stroke: "#ffffff",
                        strokeWidth: 2,
                        r: 4.5 
                    }),

                    // Unsubsidized Break-Even Label
                    Plot.text(unsubBePoint, { 
                        x: "year", 
                        y: "cf", 
                        text: d => `Base: ${d.year.toFixed(1)} yrs`, 
                        dy: 18,
                        fontSize: 10,
                        fill: "#475569",
                        stroke: "#ffffff",
                        strokeWidth: 3,
                        paintOrder: "stroke"
                    })
                ]
            };
        });
    </script>
</body>
</html>

