    sceneStateRef.current = {
      additionalTiesCount,
      isXRayMode,
      isAxlePassing,
      isSelfHealingActive,
      axlePassSpeed,
      axleZ: sceneStateRef.current.axleZ
    };
  }, [additionalTiesCount, isXRayMode, isAxlePassing, isSelfHealingActive, axlePassSpeed]);

  useEffect(() => {
    if (activeTab !== "3d" || !canvasRef.current) return;

    // Canvas Initializer
    const container = canvasRef.current.parentElement;
    const width = container.clientWidth;
    const height = container.clientHeight || 500;

